args.command:
# Check jobs agent
cat ~/.nanobot/agents/jobs/config.json 2>/dev/null | python3 -c "
import json,sys
cfg = json.load(sys.stdin)
tools = cfg.get('tools', {})
if isinstance(tools, dict):
    print('tools:', json.dumps(tools))
elif isinstance(tools, list):
    enabled = []
    for item in tools:
        if isinstance(item, dict):
            for k,v in item.items():
                if isinstance(v, list) and v and v[0] == True:
                    enabled.append(k)
    print('tools:', json.dumps(enabled))
print(f'model: {cfg.get(\"model\", \"N/A\")}')
" 2>/dev/null; echo "---"
# Also check Harper for memory_palace
python3 -c "
import json
with open('$HOME/.nanobot/agents/harper/config.json') as f:
    cfg = json.load(f)
tools = cfg.get('tools', [])
enabled = []
for item in tools:
    if isinstance(item, dict):
        for k,v in item.items():
            if isinstance(v, list) and v and v[0] == True:
                enabled.append(k)
print('Harper enabled tools:', enabled)
print('Has memory_palace:', 'memory_palace' in enabled)
"
